// Make failures visible: log a compact summary (no payloads, no personal data).
// In production, send this to Slack/PagerDuty instead of the execution log.
const e = $input.first().json;
const summary = {
  workflow: e.workflow && e.workflow.name,
  executionId: e.execution && e.execution.id,
  failedNode: e.execution && e.execution.lastNodeExecuted,
  message: e.execution && e.execution.error && e.execution.error.message,
  url: e.execution && e.execution.url,
  at: new Date().toISOString(),
};
console.error('[LendLoop automation failure]', JSON.stringify(summary));
return [{ json: summary }];
